"<script>\n"
"var S = {}, C = {};\n"
"var $ = function (id) { return document.getElementById(id); };\n"
"\n"
"function toast(msg, bad) {\n"
"  var t = $('toast');\n"
"  t.textContent = msg;\n"
"  t.className = 'on' + (bad ? ' bad' : '');\n"
"  clearTimeout(toast._t);\n"
"  toast._t = setTimeout(function () { t.className = ''; }, 3200);\n"
"}\n"
"\n"
"function fmtTime(sec) {\n"
"  sec = Math.max(0, Math.floor(sec || 0));\n"
"  var m = Math.floor(sec / 60), s = sec % 60;\n"
"  return m + ':' + (s < 10 ? '0' : '') + s;\n"
"}\n"
"var RESET = {1:'POWERON',2:'EXT',3:'SW',4:'PANIC',5:'INT_WDT',6:'TASK_WDT',\n"
"             7:'WDT',8:'DEEPSLEEP',9:'BROWNOUT',10:'SDIO'};\n"
"function fmtReset(v) { return RESET[v] ? RESET[v] + ' (' + v + ')' : String(v); }\n"
"function fmtBytes(n) {\n"
"  if (!n) return '0 B';\n"
"  var u = ['B', 'KB', 'MB', 'GB', 'TB'], i = 0;\n"
"  while (n >= 1024 && i < u.length - 1) { n /= 1024; i++; }\n"
"  return n.toFixed(n >= 10 || i === 0 ? 0 : 1) + ' ' + u[i];\n"
"}\n"
"function setVal(id, v) {\n"
"  var el = $(id);\n"
"  if (document.activeElement !== el) el.value = v;\n"
"}\n"
"function row(k, v, cls) {\n"
"  return '<div class=\"row\"><span class=\"k\">' + k + '</span><span class=\"v ' +\n"
"    (cls || '') + '\">' + (v === undefined || v === null || v === '' ? '—' : v) + '</span></div>';\n"
"}\n"
"function chip(label, value, cls) {\n"
"  return '<span class=\"chip ' + (cls || '') + '\"><span class=\"led\"></span>' +\n"
"    label + ' <b>' + value + '</b></span>';\n"
"}\n"
"\n"
"function api(path, opts) {\n"
"  return fetch(path, opts).then(function (r) {\n"
"    return r.text().then(function (t) {\n"
"      if (!r.ok) throw new Error(t || r.status);\n"
"      return t;\n"
"    });\n"
"  });\n"
"}\n"
"function key(k) {\n"
"  api('/api/key?k=' + encodeURIComponent(k), { method: 'POST' })\n"
"    .then(function () { setTimeout(refresh, 350); })\n"
"    .catch(function (e) { toast('Key failed: ' + e.message, true); });\n"
"}\n"
"\n"
"function render(s, c) {\n"
"  $('chips').innerHTML =\n"
"    chip('iAP2', s.iap2_mode ? (s.iap2_identified ? 'LINKED' : 'WAIT') : 'OFF',\n"
"         s.iap2_mode ? (s.iap2_identified ? 'ok' : 'warn') : '') +\n"
"    chip('SD', s.sd_ready ? 'READY' : 'MISSING', s.sd_ready ? 'ok' : 'bad') +\n"
"    chip('WiFi', s.ip || '—', s.ip && s.ip !== '--' ? 'ok' : 'warn');\n"
"\n"
"  $('np_title').textContent = s.title || '—';\n"
"  $('np_artist').textContent = s.iap2 ? s.iap2 : '—';\n"
"  $('np_album').textContent = s.device_name || '';\n"
"  $('play_state').textContent = s.play_status === 1 ? 'PLAYING'\n"
"    : s.play_status === 2 ? 'PAUSED' : 'STOPPED';\n"
"  $('btn_play').textContent = s.play_status === 1 ? 'PAUSE' : 'PLAY';\n"
"  var dur = (s.duration_ms || 0) / 1000, cur = (s.elapsed_ms || 0) / 1000;\n"
"  $('np_dur').textContent = fmtTime(dur);\n"
"  $('np_cur').textContent = fmtTime(cur);\n"
"  $('np_bar').style.width = dur > 0 ? Math.min(100, cur / dur * 100) + '%' : '0%';\n"
"\n"
"  $('btn_trust').disabled = !!s.iap2_mode || !!s.apple_pair_busy;\n"
"  if (s.apple_trusted) $('apple_trust').textContent = '';\n"
"  else if (s.apple_pair_status) $('apple_trust').textContent = s.apple_pair_status;\n"
"  else $('apple_trust').textContent = 'In AFC mode, connect and unlock your device, then tap Trust on its screen.';\n"
"\n"
"  $('device_rows').innerHTML =\n"
"    row('iAP2', s.iap2) +\n"
"    row('USB mux', s.usbmux) +\n"
"    row('Lockdown', s.lockdown) +\n"
"    row('AFC', s.afc) +\n"
"    row('WiFi', s.wifi, s.ip && s.ip !== '--' ? 'ok' : '') +\n"
"    row('IP', s.ip) +\n"
"    row('SD card', s.sd_ready ? fmtBytes(s.sd_used) + ' / ' + fmtBytes(s.sd_total) : 'missing',\n"
"        s.sd_ready ? '' : 'bad') +\n"
"    row('Uptime', fmtTime(s.uptime_s)) +\n"
"    row('Heap', fmtBytes(s.free_heap)) +\n"
"    row('PSRAM', fmtBytes(s.free_psram)) +\n"
"    row('Reset', fmtReset(s.reset_reason));\n"
"\n"
"  $('fw_rows').innerHTML =\n"
"    row('Firmware', s.firmware) +\n"
"    row('Build', s.build) +\n"
"    row('OTA slot', s.ota_partition) +\n"
"    row('USB mode', s.usb_mode === 2 ? 'USB-A HS & USB-C OTG' : 'USB-A HighSpeed Only');\n"
"\n"
"  $('clock_hint').textContent = (s.local_time || '—') +\n"
"    (s.rtc ? ' · RTC backed' : ' · no RTC');\n"
"\n"
"  setVal('volume', c.volume); $('vol_v').textContent = c.volume;\n"
"  setVal('brightness', c.brightness); $('bri_v').textContent = c.brightness;\n"
"  setVal('sound_mode', String(c.sound_mode));\n"
"  setVal('theme', String(c.theme));\n"
"  $('debug_log').checked = !!c.debug_log;\n"
"  $('iap2_mode').checked = !!c.iap2_mode;\n"
"  setVal('usb_mode', String(c.usb_mode));\n"
"  setVal('screen_flip', String(c.screen_flip));\n"
"  setVal('wifi_mode', String(c.wifi_mode));\n"
"  setVal('ap_ssid', c.ap_ssid || '');\n"
"  $('lib_note').textContent = s.sd_ready ? 'SD ready' : 'no SD card';\n"
"}\n"
"\n"
"var offline = false;\n"
"function refresh() {\n"
"  Promise.all([fetch('/api/status').then(function (r) { return r.json(); }),\n"
"               fetch('/api/config').then(function (r) { return r.json(); }),\n"
"               fetch('/api/power').then(function (r) { return r.json(); })\n"
"                 .catch(function () { return {}; })])\n"
"    .then(function (a) {\n"
"      S = a[0]; C = a[1];\n"
"      offline = false;\n"
"      render(S, C);\n"
"      var p = a[2] || {};\n"
"      $('power_rows').innerHTML =\n"
"        row('Bus', p.bus_mv ? (p.bus_mv / 1000).toFixed(2) + ' V' : '—') +\n"
"        row('Current', p.current_ma ? p.current_ma + ' mA' : '—') +\n"
"        row('5V rail', p.usb5v_en ? 'on' : 'off') +\n"
"        row('CHG_EN', p.chg_en ? 'on' : 'off', p.chg_en ? 'ok' : '') +\n"
"        row('CHG state', p.chg_stat, '') +\n"
"        row('nCHG_QC_EN', p.nchg_qc_en ? 'high' : 'low');\n"
"      $('charge_en').checked = !!p.chg_en;\n"
"      $('qc_high').checked = !!p.nchg_qc_en;\n"
"    })\n"
"    .catch(function () {\n"
"      if (!offline) { offline = true; toast('Device unreachable', true); }\n"
"    });\n"
"}\n"
"\n"
"function saveConfig() {\n"
"  var body = {\n"
"    screen_flip: +$('screen_flip').value,\n"
"    wifi_mode: +$('wifi_mode').value,\n"
"    sound_mode: +$('sound_mode').value,\n"
"    theme: +$('theme').value,\n"
"    debug_log: $('debug_log').checked,\n"
"    iap2_mode: $('iap2_mode').checked,\n"
"    usb_mode: +$('usb_mode').value,\n"
"    volume: +$('volume').value,\n"
"    brightness: +$('brightness').value,\n"
"    ap_ssid: $('ap_ssid').value\n"
"  };\n"
"  api('/api/config', { method: 'POST', headers: { 'Content-Type': 'application/json' },\n"
"                       body: JSON.stringify(body) })\n"
"    .then(function (t) { toast(t); refresh(); })\n"
"    .catch(function (e) { toast('Save failed: ' + e.message, true); });\n"
"}\n"
"\n"
"function saveCharge() {\n"
"  api('/api/charge?en=' + ($('charge_en').checked ? 1 : 0) +\n"
"      '&qc=' + ($('qc_high').checked ? 1 : 0), { method: 'POST' })\n"
"    .then(function (t) { toast(t); refresh(); })\n"
"    .catch(function (e) { toast('Charge failed: ' + e.message, true); });\n"
"}\n"
"\n"
"function syncTime() {\n"
"  api('/api/time', { method: 'POST', headers: { 'Content-Type': 'application/json' },\n"
"                     body: JSON.stringify({ epoch: Math.floor(Date.now() / 1000) }) })\n"
"    .then(function (t) { toast(t); refresh(); })\n"
"    .catch(function (e) { toast('Time failed: ' + e.message, true); });\n"
"}\n"
"\n"
"function reboot() {\n"
"  if (!confirm('Reboot the device?')) return;\n"
"  api('/api/reboot', { method: 'POST' }).then(function () { toast('Rebooting…'); })\n"
"    .catch(function () { toast('Rebooting…'); });\n"
"}\n"
"\n"
"function sync_media() {\n"
"  api('/api/sync', { method: 'POST' })\n"
"    .then(function (t) { toast(t); })\n"
"    .catch(function (e) { toast('Sync failed: ' + e.message, true); });\n"
"}\n"
"\n"
"function upload(path, file, prog, done) {\n"
"  if (!file) { toast('Choose a file first', true); return; }\n"
"  var x = new XMLHttpRequest();\n"
"  x.open('POST', path);\n"
"  prog.style.display = 'block';\n"
"  prog.firstElementChild.style.width = '0%';\n"
"  x.upload.onprogress = function (e) {\n"
"    if (e.lengthComputable) {\n"
"      prog.firstElementChild.style.width = (e.loaded / e.total * 100) + '%';\n"
"    }\n"
"  };\n"
"  x.onload = function () {\n"
"    prog.firstElementChild.style.width = '100%';\n"
"    if (x.status >= 200 && x.status < 300) { toast(x.responseText || 'OK'); done(x.responseText); }\n"
"    else { toast('Upload failed: ' + x.responseText, true); }\n"
"  };\n"
"  x.onerror = function () { toast('Upload failed', true); };\n"
"  x.send(file);\n"
"}\n"
"\n"
"function uploadLibrary() {\n"
"  upload('/api/library', $('lib_file').files[0], $('lib_prog'), function () {\n"
"    setTimeout(refresh, 4000);\n"
"  });\n"
"}\n"
"function uploadFirmware() {\n"
"  upload('/api/ota', $('fw_file').files[0], $('fw_prog'), function () {\n"
"    toast('Update accepted; the device is rebooting');\n"
"    setTimeout(refresh, 12000);\n"
"  });\n"
"}\n"
"function pairApple() {\n"
"  api('/api/trust', {method: 'POST'})\n"
"    .then(function (text) { toast(text); })\n"
"    .catch(function (e) { toast(e.message, true); });\n"
"}\n"
"function uploadPair() {\n"
"  if (!$('pair_file').files[0]) { toast('Choose a plist first', true); return; }\n"
"  api('/api/pair', { method: 'POST', body: $('pair_file').files[0] })\n"
"    .then(function (t) { toast(t); })\n"
"    .catch(function (e) { toast('Pair upload failed: ' + e.message, true); });\n"
"}\n"
"\n"
"function loadLog() {\n"
"  fetch('/api/log?since=0').then(function (r) { return r.text(); })\n"
"    .then(function (t) { $('log').textContent = t.slice(-20000) || '—'; })\n"
"    .catch(function (e) { $('log').textContent = 'Log unavailable: ' + e.message; });\n"
"}\n"
"\n"
"/* sliders save on release */\n"
"['volume', 'brightness'].forEach(function (id) {\n"
"  var el = $(id);\n"
"  el.addEventListener('input', function () {\n"
"    $(id === 'volume' ? 'vol_v' : 'bri_v').textContent = el.value;\n"
"  });\n"
"  el.addEventListener('change', function () {\n"
"    var body = {};\n"
"    body[id] = +el.value;\n"
"    api('/api/config', { method: 'POST', headers: { 'Content-Type': 'application/json' },\n"
"                         body: JSON.stringify(body) })\n"
"      .then(function () { toast(id + ' ' + el.value + '%'); })\n"
"      .catch(function (e) { toast('Save failed: ' + e.message, true); });\n"
"  });\n"
"});\n"
"\n"
"/* section highlight */\n"
"var links = [].slice.call(document.querySelectorAll('nav a'));\n"
"function mark() {\n"
"  var best = links[0], top = -1e9;\n"
"  links.forEach(function (a) {\n"
"    var r = document.querySelector(a.getAttribute('href')).getBoundingClientRect();\n"
"    if (r.top <= 80 && r.top > top) { top = r.top; best = a; }\n"
"  });\n"
"  links.forEach(function (a) { a.classList.toggle('on', a === best); });\n"
"}\n"
"window.addEventListener('scroll', mark, { passive: true });\n"
"\n"
"refresh();\n"
"setInterval(refresh, 2000);\n"
"</script>\n"
"</body>\n"
"</html>\n"
;

#endif /* IAP2TAB5_WEB_INDEX_H */
